	if err != nil {
		return stateLock{}, fmt.Errorf("open git common dir: %w", err)
	}
	if err := osroot.MkdirAllNoSymlink(root, SessionLockDirName, 0o750); err != nil {
		return stateLock{}, fmt.Errorf("create session lock directory: %w", err)
