		return nil, nil // not a directory, so nothing below it to report
	default:
		return nil, openErr
	}

	var found []string
	err := fs.WalkDir(walkRoot.FS(), ".", func(name string, d fs.DirEntry, err error) error {
		reported := dir
		if name != "." {
			reported = path.Join(dir, strings.TrimPrefix(name, "./"))
		}
		if err != nil {
			if name == "." && os.IsNotExist(err) {
				return nil
			}
			return err
		}
		if d.Type()&fs.ModeSymlink != 0 {
			found = append(found, reported)
		}
		return nil
	})
	if err != nil {
		return nil, err //nolint:wrapcheck // caller names the directory it asked about
	}
	return found, nil
}

// sharedRoots is the process-wide registry behind Shared. Entire anchors roots
// at three directories — .entire, the git common dir, and the worktree root —
// and each had its own memoized map before this existed. One registry means one
// place that decides a directory is opened at most once, and one Reset.
var (
	sharedMu    sync.Mutex
	sharedRoots = map[string]*os.Root{}
)

// Shared returns a process-wide *os.Root for dir, opening it at most once. The
// returned root is owned by the registry and shared with every other caller: do
// not close it.
//
// dir must be absolute. A relative key would name different directories as the
// process moved, which is the whole failure mode these roots exist to remove.
//
// A missing directory is returned unwrapped so callers can classify it with
// os.IsNotExist as well as errors.Is.
func Shared(dir string) (*os.Root, error) {
	if !filepath.IsAbs(dir) {
		return nil, fmt.Errorf("osroot: %q is not absolute", dir)
	}
	cleaned := filepath.Clean(dir)

	sharedMu.Lock()
	defer sharedMu.Unlock()

	if root, ok := sharedRoots[cleaned]; ok {
		return root, nil
	}
	root, err := os.OpenRoot(cleaned)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, err //nolint:wrapcheck // see doc comment
		}
		return nil, fmt.Errorf("open %s: %w", cleaned, err)
	}
	sharedRoots[cleaned] = root
	return root, nil
}

// OpenChild opens a root for the directory name inside parent, WITHOUT
// memoizing it: the caller owns the returned root and must Close it.
//
// It is SharedChild's short-lived counterpart, and it exists so that opening a
// subdirectory of an anchor is never a bare parent.OpenRoot(name). os.Root
// refuses a symlink that escapes parent but follows one pointing elsewhere
// INSIDE it, so a bare OpenRoot silently accepts a redirected
// .git/entire-sessions. The Lstat before and the SameFile after are the same
// pair SharedChild uses, and they close the Lstat/OpenRoot race: once the
// identity is confirmed, a later replacement cannot redirect the handle.
//
// A missing directory is returned unwrapped so callers can classify it with
// os.IsNotExist.
func OpenChild(parent *os.Root, name string) (*os.Root, error) {
	if parent == nil {
		return nil, errors.New("osroot: parent root is required")
	}
	before, err := parent.Lstat(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if before.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	if !before.IsDir() {
		return nil, fmt.Errorf("%s: %w", name, ErrWalkRootNotDirectory)
	}

	root, err := parent.OpenRoot(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedRoot(parent, name, root); err != nil {
		_ = root.Close()
		return nil, err
	}
	return root, nil
}

// validateOpenedRoot confirms that name still names a real directory and that
// it is the object the opened root holds.
func validateOpenedRoot(parent *os.Root, name string, root *os.Root) error {
	pathInfo, err := parent.Lstat(name)
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	openedInfo, err := root.Stat(".")
	if err != nil {
		return err //nolint:wrapcheck // preserve original error classification
	}
	if pathInfo.Mode()&os.ModeSymlink != 0 || !pathInfo.IsDir() || !os.SameFile(pathInfo, openedInfo) {
		return fmt.Errorf("%s changed while it was being opened: %w", name, ErrSymlinkedPath)
	}
	return nil
}

// SharedChild returns a shared root for name beneath parent. Unlike opening the
// assembled absolute path, this keeps name inside an already-trusted root and
// refuses a symlink at the child boundary. The post-open identity check closes
// the Lstat/OpenRoot race.
func SharedChild(parent *os.Root, dir, name string) (*os.Root, error) {
	if parent == nil {
		return nil, errors.New("osroot: parent root is required")
	}
	if !filepath.IsAbs(dir) {
		return nil, fmt.Errorf("osroot: %q is not absolute", dir)
	}
	cleaned := filepath.Clean(dir)

	sharedMu.Lock()
	defer sharedMu.Unlock()
	if root, ok := sharedRoots[cleaned]; ok {
		return root, nil
	}

	before, err := parent.Lstat(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	// Classified apart, matching OpenChild: ErrWalkRootNotDirectory's own doc
	// comment says conflating "replace this link" with "this is a regular file"
	// is how a user gets told to fix the wrong thing.
	if before.Mode()&os.ModeSymlink != 0 {
		return nil, fmt.Errorf("%s: %w", name, ErrSymlinkedPath)
	}
	if !before.IsDir() {
		return nil, fmt.Errorf("%s: %w", name, ErrWalkRootNotDirectory)
	}

	root, err := parent.OpenRoot(name)
	if err != nil {
		return nil, err //nolint:wrapcheck // preserve original error classification
	}
	if err := validateOpenedRoot(parent, name, root); err != nil {
		_ = root.Close()
		return nil, err
	}

	sharedRoots[cleaned] = root
	return root, nil
}
package flock

import (
	"errors"
	"io/fs"
	"os"

	"github.com/entireio/cli/cmd/entire/cli/osroot"
)

// openLockFileIn opens the lock file, creating it if needed, without ever
// asking for O_CREATE *without* O_EXCL.
//
// That combination is the one operation macOS gets wrong: when several callers
// race the first creation of a single name through openat(2), most of them get
// a spurious ENOENT instead of a descriptor, measured at 25-75% under
// contention, on macOS 26.6 (25G72) and 26.6.2 (25G83), reproducible in plain C
// with no Go involved. Nothing else races: O_CREATE|O_EXCL, a plain open of an
// existing file, mkdirat/symlinkat/linkat/renameat, and full-path open(2) are
// all correct, and Linux is unaffected entirely. Only openat's create-or-open
// fallback is broken.
//
// This matters here more than anywhere else in the tree, because a lock nobody
// can take is a lock that silently stops serializing: callers saw
// "acquire state lock: ... no such file or directory" and concurrent session
// state merges were lost. The pre-os.Root code used a full path, so this is a
// regression the root migration would otherwise introduce on the platform we
// develop on.
//
// Splitting create-or-open into an exclusive create plus a plain open avoids
// the broken path entirely, and is deterministic rather than a retry: measured
// 0 failures in 6000 racing opens where the single-call form failed 4806 times.
// The loop covers only the vanishingly rare case of the file being removed
// between the two steps. Lock files are never unlinked (see ClearSessionState),
// so in practice it runs once.
//
// Both steps go through osroot.OpenFileNoFollow rather than root.OpenFile. An
// os.Root refuses a symlink that escapes it but follows one pointing elsewhere
// inside it, and the plain-open fallback is reached precisely when something
// already exists at the name, which is where a planted link would sit. No
// caller can be reached that way today: every AcquireIn name resolves through a
// git common dir root, and git will not check a path out into .git. The refusal
// is here so that stays true if a worktree-anchored caller is ever added, since
// the worktree is the one tree a checkout does control. It keeps the two-step
// split intact, so the macOS behaviour above is unaffected.
func openLockFileIn(root *os.Root, name string) (*os.File, error) {
	var err error
	for range 3 {
		var f *os.File
		f, err = osroot.OpenFileNoFollow(root, name, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
		if err == nil {
			return f, nil
		}
		if !errors.Is(err, fs.ErrExist) {
			return nil, err //nolint:wrapcheck // AcquireContextIn wraps this; wrapping twice would bury the cause
		}
		// It exists now, so open it without O_CREATE.
		f, err = osroot.OpenFileNoFollow(root, name, os.O_RDWR, 0)
		if err == nil {
			return f, nil
		}
		if !errors.Is(err, fs.ErrNotExist) {
			return nil, err //nolint:wrapcheck // AcquireContextIn wraps this; wrapping twice would bury the cause
		}
		// Removed between the two steps; start over.
	}
	return nil, err //nolint:wrapcheck // AcquireContextIn wraps this; wrapping twice would bury the cause
}
//go:build unix

// Package flock provides a small cross-process advisory-lock primitive built
// on POSIX flock (Unix) / LockFileEx (Windows). It exists so that checkpoint
// and strategy can both serialize on shared resources without one taking
// the other as an import dependency.
package flock

import (
	"context"
	"errors"
	"fmt"
	"os"
	"syscall"
	"time"
)

// pollInterval is how often the bounded AcquireContext path retries a
// non-blocking lock while waiting for a deadline.
const pollInterval = 25 * time.Millisecond

// Acquire takes an exclusive advisory lock on path, creating the file if
// needed. The returned release closes the file, which drops the flock.
// Callers must invoke release exactly once. The lock file persists between
// runs — flock state is held by the file descriptor, not by the inode on
// disk — so the lockfile contents are immaterial.
//
// Acquire blocks indefinitely until the lock is available. Use AcquireContext
// with a deadline to bound the wait.
func Acquire(path string) (release func(), err error) {
	return AcquireContext(context.Background(), path)
}

// AcquireContext behaves like Acquire but honors ctx. When ctx carries a
// deadline it polls a non-blocking lock until the lock is acquired or the
// deadline/cancellation fires, returning a wrapped ctx.Err() on timeout. When
// ctx has no deadline it takes the same blocking kernel path as Acquire, so
// existing callers keep their exact behavior. This lets latency-critical hooks
// (turn-start) bound their wait and degrade gracefully instead of stalling
// behind a long-running lock holder (e.g. checkpoint condensation).
func AcquireContext(ctx context.Context, path string) (release func(), err error) {
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600) //nolint:gosec // caller is responsible for path validation
	if err != nil {
		return nil, fmt.Errorf("open flock: %w", err)
	}
	return lockFile(ctx, f)
}

// AcquireIn is Acquire for a lock file named inside root. It is the form the
// .git-resident locks use: their names carry agent-supplied session IDs, so
// resolving them through the git common dir's root keeps a name that escaped
// validation from naming a file outside the clone.
func AcquireIn(root *os.Root, name string) (release func(), err error) {
	return AcquireContextIn(context.Background(), root, name)
}

// AcquireContextIn is AcquireContext for a lock file named inside root.
func AcquireContextIn(ctx context.Context, root *os.Root, name string) (release func(), err error) {
	f, err := openLockFileIn(root, name)
	if err != nil {
		return nil, fmt.Errorf("open flock: %w", err)
	}
	return lockFile(ctx, f)
}

// lockFile holds the locking logic shared by the path- and root-based entry
// points, which differ only in how the file was opened.
func lockFile(ctx context.Context, f *os.File) (release func(), err error) {
	// Fast path: no deadline -> block in the kernel exactly like the historical
	// Acquire. This preserves behavior (and efficiency) for callers that must
	// wait as long as it takes, such as turn-end checkpoint condensation.
	if _, hasDeadline := ctx.Deadline(); !hasDeadline {
		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil { //nolint:gosec // file descriptors are non-negative; standard Go pattern for syscall.Flock
			_ = f.Close()
			return nil, fmt.Errorf("flock: %w", err)
		}
		return func() { _ = f.Close() }, nil
	}

	// Bounded path: poll a non-blocking lock until acquired or ctx is done.
	for {
		lockErr := syscall.Flock(int(f.Fd()), syscall.LOCK_EX|syscall.LOCK_NB) //nolint:gosec // see above
		if lockErr == nil {
			return func() { _ = f.Close() }, nil
		}
		if !errors.Is(lockErr, syscall.EWOULDBLOCK) {
			_ = f.Close()
			return nil, fmt.Errorf("flock: %w", lockErr)
		}
		if err := ctx.Err(); err != nil {
			_ = f.Close()
			return nil, fmt.Errorf("flock: %w", err)
		}
		select {
		case <-ctx.Done():
			_ = f.Close()
			return nil, fmt.Errorf("flock: %w", ctx.Err())
		case <-time.After(pollInterval):
		}
	}
}
	lockPath, err := stateLockPath(ctx, sessionID)
	if err != nil {
		return nil, false, nil, fmt.Errorf("resolve state lock path: %w", err)
	}
	// Bound the acquisition when the caller opted in (TurnStart), so a
	// best-effort mutation can't stall behind a long-running lock holder. The
	// deadline is shared across the whole path, so several mutations don't sum
	// their waits. Only the acquire is bounded — the mutation runs under the
	// original ctx.
	var flockRel func()
	if deadline, ok := sessionLockDeadlineFromContext(ctx); ok {
		acqCtx, cancel := context.WithDeadline(ctx, deadline)
		flockRel, err = flock.AcquireContext(acqCtx, lockPath)
		cancel()
	} else {
		flockRel, err = flock.Acquire(lockPath)
	}
	if err != nil {
		return nil, false, nil, fmt.Errorf("acquire state lock: %w", err)
	}

	gate.mu.Lock()
	gate.owner = gid
	gate.depth = 1
	gate.flockRel = flockRel
	gate.mu.Unlock()

	return gate, true, func() {
		gate.mu.Lock()
		gate.depth--
		if gate.depth == 0 {
			rel := gate.flockRel
			gate.flockRel = nil
			gate.owner = 0
			gate.mu.Unlock()
			rel()
			return
		}
		gate.mu.Unlock()
	}, nil
}

// WithSessionStateLocks acquires the per-session state lock in each git common
// dir, then runs fn. Lock paths are deduplicated and sorted so callers that
// span repositories or worktrees can safely acquire more than one lock.
func WithSessionStateLocks(ctx context.Context, sessionID string, commonDirs []string, fn func() error) error {
	lockPaths, err := sessionStateLockPaths(sessionID, commonDirs)
	if err != nil {
		return err
	}

	releases := make([]func(), 0, len(lockPaths))
	releaseAll := func() {
		for i := len(releases) - 1; i >= 0; i-- {
			releases[i]()
		}
	}
	for _, lockPath := range lockPaths {
		if err := ctx.Err(); err != nil {
			releaseAll()
			return fmt.Errorf("session state lock canceled: %w", err)
		}
		release, err := flock.Acquire(lockPath)
		if err != nil {
			releaseAll()
			return fmt.Errorf("acquire session state lock: %w", err)
		}
		releases = append(releases, release)
	}
	defer releaseAll()

	return fn()
}

func sessionStateLockPaths(sessionID string, commonDirs []string) ([]string, error) {
	lockPaths := make([]string, 0, len(commonDirs))
	seen := make(map[string]struct{}, len(commonDirs))
	for _, commonDir := range commonDirs {
		if strings.TrimSpace(commonDir) == "" {
			return nil, errors.New("empty git common dir")
		}
		physicalDir, err := filepath.Abs(commonDir)
		if err != nil {
			return nil, fmt.Errorf("resolve git common dir %q for locking: %w", commonDir, err)
		}
		physicalDir, err = filepath.EvalSymlinks(physicalDir)
		if err != nil {
			return nil, fmt.Errorf("resolve physical git common dir %q for locking: %w", commonDir, err)
		}
		lockPath, err := stateLockPathInCommonDir(physicalDir, sessionID)
		if err != nil {
			return nil, err
		}
		if _, ok := seen[lockPath]; ok {
			continue
		}
		seen[lockPath] = struct{}{}
		lockPaths = append(lockPaths, lockPath)
	}
	slices.Sort(lockPaths)
	return lockPaths, nil
}

// ErrMutationSkip signals MutateSessionState to skip the save without
// treating fn's return as an error. Use it when the mutation function
// observes the loaded state and decides no write is needed (for example,
// when a merge produces no new entries).
var ErrMutationSkip = errors.New("session state mutation skipped")

// ErrStateNotFound is returned by MutateSessionState when no state file
// exists for the session ID (typically because the event arrived before
// InitializeSession ran). Callers that need to distinguish "no state"
// from a successful no-op can branch on errors.Is(err, ErrStateNotFound).
var ErrStateNotFound = errors.New("session state not found")

// RecordFilesTouched merges paths into the session's FilesTouched, used by
// mid-turn lifecycle events (per-tool-use hooks) so PostCommit's carry-forward
// decision sees an accurate file list. Caller must pre-normalize paths to
// repo-relative form. No-ops when the session state doesn't exist or the
// merge produced no changes.
func RecordFilesTouched(ctx context.Context, sessionID string, modified, added, deleted []string) error {
	if len(modified) == 0 && len(added) == 0 && len(deleted) == 0 {
		return nil
	}
	err := MutateSessionState(ctx, sessionID, func(state *SessionState) error {
		merged := mergeFilesTouched(state.FilesTouched, modified, added, deleted)
		if slices.Equal(merged, state.FilesTouched) {
			return ErrMutationSkip
		}
		state.FilesTouched = merged
		return nil
	})
	if errors.Is(err, ErrStateNotFound) {
		return nil
	}
	return err
}

// stateLockPath returns the lock file path for a session. Lock files live in
// .git/entire-session-locks/ (a sibling to entire-sessions/) so callers that
// enumerate session state files don't have to filter lock entries. A
// separate file (rather than locking the state file itself) keeps the lock
// holder distinct from the data — Save's atomic-rename pattern would
// otherwise unlink the inode the flock is held on.
func stateLockPath(ctx context.Context, sessionID string) (string, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return "", fmt.Errorf("resolve worktree root: %w", err)
	}
	metadata, err := gitrepo.ResolveWorktreeMetadata(worktreeRoot)
	if err != nil {
		return "", fmt.Errorf("resolve worktree metadata: %w", err)
	}
	return stateLockPathInCommonDir(metadata.CommonDir, sessionID)
}

