		AgentName:    agentName,
		Skills:       cfg.Skills,
		Prompt:       prompt,
		StartingSHA:  cfg.StartingSHA,
		StartedAt:    time.Now().UTC(),
		WorktreePath: worktreePath,
	}); err != nil {
		return fmt.Errorf("write pending marker: %w", err)
	}

	fmt.Fprintf(out, "%s does not have an Entire review runner adapter yet. Marker written.\n", agentName)
	if len(cfg.Skills) > 0 {
		fmt.Fprintf(out, "Start %s manually and run these skills:\n", agentName)
		for i, skill := range cfg.Skills {
			fmt.Fprintf(out, "  %d. %s\n", i+1, skill)
		}
		fmt.Fprintln(out)
	}
	if prompt != "" {
	}
	if err != nil {
		return nil, fmt.Errorf("read review manifest dir: %w", err)
	}

	manifests := make([]LocalReviewManifest, 0, len(entries))
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}
		b, readErr := osroot.ReadFileNoFollow(root, dir+"/"+entry.Name())
		if readErr != nil {
			return nil, fmt.Errorf("read review manifest %s: %w", entry.Name(), readErr)
