	if err := jsonutil.WriteFileAtomicIn(root, pendingMarkerName, data, 0o600); err != nil {
		return fmt.Errorf("write marker: %w", err)
	}
	return nil
}

// ReadPendingReviewMarker returns the marker if one exists.
// ok=false with err=nil indicates "no pending review."
func ReadPendingReviewMarker(ctx context.Context) (PendingReviewMarker, bool, error) {
	root, err := pendingMarkerRoot(ctx)
	if err != nil {
		return PendingReviewMarker{}, false, err
	}
	data, err := osroot.ReadFileNoFollow(root, pendingMarkerName)
	if errors.Is(err, os.ErrNotExist) {
		return PendingReviewMarker{}, false, nil
	}
	if err != nil {
		return PendingReviewMarker{}, false, fmt.Errorf("read marker: %w", err)
	}
	var m PendingReviewMarker
	if err := json.Unmarshal(data, &m); err != nil {
		return PendingReviewMarker{}, false, fmt.Errorf("parse marker: %w", err)
	}
	return m, true, nil
}

// ClearPendingReviewMarker removes the marker. Missing file is not an error.
func ClearPendingReviewMarker(ctx context.Context) error {
	root, err := pendingMarkerRoot(ctx)
	if err != nil {
		return err
	}
	if err := root.Remove(pendingMarkerName); err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("remove marker: %w", err)
	}
	return nil
}

// RunMarkerFallback handles review for agents that do not yet have an Entire
// review-runner adapter by writing the pending-review marker file and printing
// manual-start guidance. The user is told to open the agent themselves and run
// the configured skills.
//
// The marker is NOT auto-adopted by anything — the lifecycle hook reads
// ENTIRE_REVIEW_* env vars on the spawned process, not the marker file.
// For adapterless review agents the user starts the agent manually, so no env
// inheritance happens. The marker exists purely so that `entire session
// attach --review <session-id>` has a record of what the user was asked to
// review when tagging the session after the fact.
//
// agentName must be the agent's registry key (e.g. "cursor").
// cfg carries skills and the starting SHA.
// worktreePath scopes the marker so sessions in other worktrees don't claim it.
// out is the destination for user-facing guidance.
func RunMarkerFallback(ctx context.Context, agentName string, cfg reviewtypes.RunConfig, worktreePath string, out io.Writer) error {
	prompt := ComposeReviewPrompt(cfg)
	if err := WritePendingReviewMarker(ctx, PendingReviewMarker{
		AgentName:    agentName,
		Skills:       cfg.Skills,
		Prompt:       prompt,
		StartingSHA:  cfg.StartingSHA,
		StartedAt:    time.Now().UTC(),
		WorktreePath: worktreePath,
	}); err != nil {
		return fmt.Errorf("write pending marker: %w", err)
	}

	fmt.Fprintf(out, "%s does not have an Entire review runner adapter yet. Marker written.\n", agentName)
	if len(cfg.Skills) > 0 {
		fmt.Fprintf(out, "Start %s manually and run these skills:\n", agentName)
		for i, skill := range cfg.Skills {
			fmt.Fprintf(out, "  %d. %s\n", i+1, skill)
		}
		fmt.Fprintln(out)
	}
	if prompt != "" {
	}
	if err != nil {
		return nil, fmt.Errorf("read review manifest dir: %w", err)
	}

	manifests := make([]LocalReviewManifest, 0, len(entries))
	for _, entry := range entries {
		if entry.IsDir() || filepath.Ext(entry.Name()) != ".json" {
			continue
		}
		b, readErr := osroot.ReadFileNoFollow(root, dir+"/"+entry.Name())
		if readErr != nil {
			return nil, fmt.Errorf("read review manifest %s: %w", entry.Name(), readErr)
		}
		var manifest LocalReviewManifest
		if err := json.Unmarshal(b, &manifest); err != nil {
			return nil, fmt.Errorf("decode review manifest %s: %w", entry.Name(), err)
		}
		if worktreeRoot != "" && manifest.WorktreePath != "" && manifest.WorktreePath != worktreeRoot {
			continue
		}
		manifests = append(manifests, manifest)
	}
	sort.SliceStable(manifests, func(i, j int) bool {
		return manifests[i].CreatedAt.After(manifests[j].CreatedAt)
	})
	return manifests, nil
}

// localReviewManifestName is the manifest directory inside the git common dir.
const localReviewManifestName = "entire-review/manifests"

// localReviewManifestStore returns the shared *os.Root over the git common dir
// and the manifest directory's name inside it.
//
// The common-dir resolution comes from gitdir rather than a fourth hand-rolled
// `git rev-parse --git-common-dir` — this file had one, and it was the only copy
// that remembered to resolve a relative answer against the worktree root.
func localReviewManifestStore(ctx context.Context) (*os.Root, string, error) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, "", fmt.Errorf("resolve worktree root: %w", err)
	}
	commonDir, err := gitdir.CommonDirForWorktree(ctx, worktreeRoot)
	if err != nil {
		return nil, "", fmt.Errorf("resolve git common dir: %w", err)
	}
	root, err := gitdir.OpenAt(commonDir)
	if err != nil {
		return nil, "", fmt.Errorf("open git common dir: %w", err)
	}
	return root, localReviewManifestName, nil
}

func localReviewManifestFilename(manifest LocalReviewManifest) string {
	name := reviewManifestTimeHandle(manifest.CreatedAt)
	if len(manifest.Sources) > 0 && manifest.Sources[0].SessionID != "" {
		name += "-" + safeManifestFilenamePart(manifest.Sources[0].SessionID)
	}
	return name + ".json"
}

func safeManifestFilenamePart(value string) string {
	value = strings.TrimSpace(value)
	if value == "" {
		return "review"
	}
	var b strings.Builder
	for _, r := range value {
		if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_' || r == '.' {
			b.WriteRune(r)
			continue
		}
		b.WriteByte('-')
	}
	return b.String()
}

