// countSweepableZombies counts the sessions in states that nominate a
// background sweep. Pure so the spawn decision is unit-testable.
func countSweepableZombies(states []*session.State, now time.Time) int {
	n := 0
	for _, st := range states {
		if isSweepableZombie(st, now) {
			n++
		}
	}
	return n
}

// sweepSpawn is the process-spawn seam used by maybeSpawnSessionSweep.
// Swapped in tests so they can assert the spawn decision (including the
// throttle) without forking a real subprocess (a real `go test` binary doesn't
// understand `__sweep_sessions` as an argument). Production code always uses
// spawnDetachedSessionSweepProcess.
var sweepSpawn = spawnDetachedSessionSweepProcess

// resolveSweepMetadata is the repository-scope seam used by
// maybeSpawnSessionSweep. Swapped in tests to prove a throttle-key failure
// fails closed without depending on a malformed repository fixture.
var resolveSweepMetadata = gitrepo.ResolveWorktreeMetadata

// spawnDetachedSessionSweepProcess starts `entire __sweep_sessions` as a
// detached child so the sweep's repo work can't add latency to the
// session-start hook that spawned it. The child runs from the worktree root
// because the sweep resolves the repo and session-state directory from its
// working directory.
func spawnDetachedSessionSweepProcess(worktreeRoot string) {
	execx.SpawnDetached(worktreeRoot, "__sweep_sessions")
}

// sessionSweepSpawnThrottle bounds how often the session-start hook forks a
// detached sweep child for a given repo. A zombie that persistently fails to
// condense re-nominates a spawn on every session start; without this guard a
// burst of hooks (or an agent that restarts sessions rapidly) would fork one
// child per hook, each re-opening the repo just to fail the same way. 15
// minutes comfortably covers a burst and a slow in-flight sweep while still
// retrying a transient failure within the same working session.
const sessionSweepSpawnThrottle = 15 * time.Minute

// sweepRecentlySpawned reports whether a detached sweep was spawned for this
// repo within sessionSweepSpawnThrottle and, when it wasn't, records now as
// the most recent spawn. Same flock-serialized marker mechanism as the
// trail-enablement refresh (see recentlySpawnedMarker), with its own marker.
func sweepRecentlySpawned(commonDir string, now time.Time) bool {
	return recentlySpawnedMarker(commonDir, "session-sweep-spawn", sessionSweepSpawnThrottle, now)
}

// maybeSpawnSessionSweep fires one detached __sweep_sessions child when the
// session-state files nominate a zombie. Called from the session-start hook:
// listing the state files is a small shared-directory read, and the sweep
// itself runs detached, so the hook's latency budget is untouched. Best-effort
// throughout — a failure here must never fail the hook.
//
// Spawns are throttled through a flock-serialized marker in the shared
// git-common-dir (sweepRecentlySpawned), so a burst of concurrent or rapid
// session starts collapses to one child per sessionSweepSpawnThrottle window.
// Redundant sweeps re-check under the per-session lock and no-op once one has
// succeeded; a zombie that persistently fails to condense is retried — and
// fails — once per throttle window, which we accept.
func maybeSpawnSessionSweep(ctx context.Context) {
	logCtx := logging.WithComponent(ctx, "session-sweep")
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		logging.Debug(logCtx, "skipping sweep spawn: could not resolve worktree root",
			slog.String("error", err.Error()))
		return
	}
	metadata, err := resolveSweepMetadata(root)
	if err != nil {
		logging.Debug(logCtx, "skipping sweep spawn: could not resolve git common dir",
			slog.String("error", err.Error()))
		return
	}
	// Zombie discovery deliberately precedes the throttle check. The shared
	// marker is check-and-record, so consulting it before discovery would burn
	// the whole throttle window on the overwhelmingly common no-zombie case. A
	// read-only marker check would permit reordering if this scan becomes a
	// measurable hook-latency cost.
	states, err := strategy.ListSessionStates(ctx)
	if err != nil {
		logging.Warn(logCtx, "skipping sweep check", slog.String("error", err.Error()))
		return
	}
	n := countSweepableZombies(states, time.Now())
	if n == 0 {
		return
		// re-forks a refresh child for this repo forever (see
		// trailRefreshSpawnThrottle above), because the cache is never
		// written and so never leaves "unknown".
		if saveErr := saveTrailsEnabledForScope(ctx, scope, false, time.Now()); saveErr != nil {
			logging.Debug(logCtx, "trails enablement refresh failed to save not-onboarded scope", "error", saveErr.Error())
		}
		return nil
	}
	if err != nil {
		logging.Debug(logCtx, "trails enablement refresh skipped: authenticated client unavailable", "error", err.Error())
		return nil
	}
	// Best-effort: this runs from the detached __refresh_trail_enablement
	// subprocess (stdout/stderr discarded, see newRefreshTrailEnablementCmd),
	// so a transient network/API failure here must not surface as a non-zero
	// process exit — there's no one watching it and no user-visible benefit,
	// only a spurious failure signal. The failure is still diagnosable via the
	// debug log above.
	if _, err := refreshTrailsEnabledCacheForScope(ctx, client, scope); err != nil {
		logging.Debug(logCtx, "trails enablement refresh failed", "error", err.Error())
		return nil
	}
	logging.Debug(logCtx, "trails enablement refresh completed", "enabled_repo_key", scope.RepoKey)
	return nil
}

// trailRefreshSpawn is the process-spawn seam used by
// spawnDetachedTrailEnablementRefresh. Swapped in tests so they can assert
// SessionStart never blocks on it without forking a real subprocess (a real
// `go test` binary doesn't understand `__refresh_trail_enablement` as an
// argument). Production code always uses spawnDetachedTrailRefreshProcess.
var trailRefreshSpawn = spawnDetachedTrailRefreshProcess

// spawnDetachedTrailRefreshProcess starts `entire __refresh_trail_enablement`
// as a detached child so the trails-enablement network refresh can't add
// latency to the SessionStart hook that spawned it. The child runs from the
// worktree root because the refresh resolves the origin remote and
// git-common-dir for cache storage from its working directory.
func spawnDetachedTrailRefreshProcess(worktreeRoot string) {
	execx.SpawnDetached(worktreeRoot, "__refresh_trail_enablement")
}

// trailRefreshSpawnThrottle bounds how often SessionStart forks a detached
// refresh child for a given repo. When the API host is unreachable the refresh
// never writes the cache, so cachedTrailsEnablementForScope stays unknown and
// the hourly TTL never starts — without this guard every SessionStart (and
// every concurrent worktree) would fork a fresh child that re-opens the repo,
// re-resolves auth, and re-dials the dead host. Tying the window to the child's
// own timeout collapses a burst of hooks to roughly one child per window while
// still retrying promptly once the host recovers.
const trailRefreshSpawnThrottle = trailEnablementRefreshTimeout

// spawnDetachedTrailEnablementRefresh starts a detached child process that
// runs runTrailEnablementRefresh in the background. Best-effort: if the
// worktree root can't be resolved or the subprocess can't be spawned, the
// cache simply stays unknown and the next SessionStart tries again. A recent
// spawn for the same repo short-circuits so a burst of hooks doesn't fork a
// herd of redundant refresh children (see trailRefreshRecentlySpawned).
func spawnDetachedTrailEnablementRefresh(ctx context.Context) {
	worktreeRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return
	}
	if metadata, metadataErr := gitrepo.ResolveWorktreeMetadata(worktreeRoot); metadataErr == nil &&
		trailRefreshRecentlySpawned(metadata.CommonDir, time.Now()) {
		return
	}
	trailRefreshSpawn(worktreeRoot)
}

// trailRefreshRecentlySpawned reports whether a detached refresh was spawned for
// this repo within trailRefreshSpawnThrottle and, when it wasn't, records now as
// the most recent spawn. The read-and-record is serialized with a flock keyed to
// the shared git-common-dir (so every worktree of the repo agrees), collapsing a
// burst of concurrent SessionStart hooks to a single child rather than one per
// hook. Best-effort: any error resolving, locking, or writing the marker falls
// through to spawning — never worse than before this guard existed.
func trailRefreshRecentlySpawned(commonDir string, now time.Time) bool {
	return recentlySpawnedMarker(commonDir, "trail-refresh-spawn", trailRefreshSpawnThrottle, now)
}

